import json
from typing import Any

from fastapi import APIRouter, Depends

from app.config import Settings, get_settings

router = APIRouter(prefix="/v1/metrics", tags=["Metrics"])


@router.get("/benchmark")
async def get_benchmark_metrics(
    settings: Settings = Depends(get_settings),
) -> dict[str, Any]:
    # Look for live eval summary if generated by benchmark scripts
    summary_path = settings.DATA_DIR.parent / "eval" / "results" / "summary.json"
    if summary_path.exists():
        try:
            with open(summary_path, encoding="utf-8") as f:
                data = json.load(f)
                if data.get("status") != "no_benchmark_yet" and "benchmarks" in data:
                    return data
        except Exception:
            pass

    # Fallback to fixture if it contains measured benchmarks
    fixture_path = settings.FIXTURES_DIR / "benchmark_summary.json"
    if fixture_path.exists():
        try:
            with open(fixture_path, encoding="utf-8") as f:
                data = json.load(f)
                if data.get("status") != "no_benchmark_yet" and "benchmarks" in data:
                    return data
        except Exception:
            pass

    return {
        "status": "no_benchmark_yet",
        "model": settings.LLM_MODEL,
        "gpu": "AMD Instinct (Benchmark Pending)",
        "message": (
            "No real benchmarks recorded yet. Run eval/bench_latency.py to populate metrics."
        ),
    }


